import base64, textwrap
script = r'''
import io
import os
import re
import sys
import zipfile
import statistics
import xml.etree.ElementTree as ET

NS_MAIN = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
NS_REL = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'
NS_PKG_REL = '{http://schemas.openxmlformats.org/package/2006/relationships}'

def col_to_index(cell_ref):
    letters = ''.join(ch for ch in cell_ref if ch.isalpha())
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch.upper()) - ord('A') + 1)
    return n - 1

def text_of(elem):
    if elem is None:
        return ''
    return ''.join(t.text or '' for t in elem.iter() if t.tag == NS_MAIN + 't')

def sheet_path_from_workbook(zf):
    wb = ET.fromstring(zf.read('xl/workbook.xml'))
    rels = ET.fromstring(zf.read('xl/_rels/workbook.xml.rels'))
    relmap = {r.attrib['Id']: r.attrib['Target'] for r in rels.findall(NS_PKG_REL + 'Relationship')}
    sheets = wb.find(NS_MAIN + 'sheets')
    first_sheet = sheets.find(NS_MAIN + 'sheet')
    rid = first_sheet.attrib[NS_REL + 'id']
    target = relmap[rid]
    if target.startswith('/'):
        return target.lstrip('/')
    if target.startswith('xl/'):
        return target
    return 'xl/' + target

def read_xlsx_bytes(data):
    with zipfile.ZipFile(io.BytesIO(data)) as zf:
        shared = []
        if 'xl/sharedStrings.xml' in zf.namelist():
            root = ET.fromstring(zf.read('xl/sharedStrings.xml'))
            for si in root.findall(NS_MAIN + 'si'):
                shared.append(text_of(si))
        sheet_path = sheet_path_from_workbook(zf)
        root = ET.fromstring(zf.read(sheet_path))
        rows = []
        for row in root.iter(NS_MAIN + 'row'):
            vals = {}
            max_idx = -1
            for c in row.findall(NS_MAIN + 'c'):
                ref = c.attrib.get('r', '')
                idx = col_to_index(ref) if ref else max_idx + 1
                max_idx = max(max_idx, idx)
                t = c.attrib.get('t')
                v = c.find(NS_MAIN + 'v')
                if t == 's':
                    raw = v.text if v is not None and v.text is not None else ''
                    value = shared[int(raw)] if raw "'!= '"'' else ''
                elif t == 'inlineStr':
                    value = text_of(c.find(NS_MAIN + 'is'))
                else:
                    value = v.text if v is not None and v.text is not None else ''
                vals[idx] = value
            if max_idx >= 0:
                rows.append([vals.get(i, '') for i in range(max_idx + 1)])
        return rows

def cell(row, idx):
    if idx is None or idx >= len(row):
        return ''
    return str(row[idx]).strip()

def norm_header(value):
    return str(value).strip()

def index_headers(header_row):
    idx = {}
    for i, h in enumerate(header_row):
        h = norm_header(h)
        if h and h not in idx:
            idx[h] = i
    return idx

def parse_float(value):
    s = str(value).strip()
    if not s:
        return None
    try:
        return float(s)
    except ValueError:
        return None

def sample_key(value):
    s = str(value).strip()
    if re.fullmatch(r'\\d+\\.0', s):
        s = s[:-2]
    return s

def key_from_variant_filename(name):
    base = os.path.basename(name)
    m = re.search(r'_CHIP_(.+)\\.xlsx"'$'"', base)
    if not m:
        return None
    token = m.group(1)
    if re.match(r'"'^'"\\d+', token):
        return re.match(r'"'^('"\\d+)', token).group(1)
    return token

def split_genes(value):
    return {g.strip() for g in re.split(r'[,;]', str(value)) if g.strip()}

archive_path, answer_path, counts_path, summary_path = sys.argv[1:5]
with zipfile.ZipFile(archive_path) as archive:
    members = [n for n in archive.namelist() if n.lower().endswith('.xlsx') and not n.endswith('/')]
    by_base = {os.path.basename(n): n for n in members}

    chip_rows = read_xlsx_bytes(archive.read(by_base['230214_Schenz_et_al_2022_CHIP_Genes.xlsx']))
    chip_genes = {cell(r, 0) for r in chip_rows if cell(r, 0)}

    trio_rows = read_xlsx_bytes(archive.read(by_base['230215_Trio_Status.xlsx']))
    trio_header = index_headers(trio_rows[0])
    sid_i = trio_header['Sample ID']
    role_i = trio_header['Status']
    blm_i = trio_header['BLM Mutation Status']
    carriers = {}
    for r in trio_rows[1:]:
        sid = sample_key(cell(r, sid_i))
        blm = cell(r, blm_i)
        if blm == 'Carrier':
            carriers[sid] = {'role': cell(r, role_i), 'blm': blm}

    variant_members = {}
    for n in members:
        base = os.path.basename(n)
        if base in ('230214_Schenz_et_al_2022_CHIP_Genes.xlsx', '230215_Trio_Status.xlsx'):
            continue
        k = key_from_variant_filename(n)
        if k:
            variant_members[k] = n

    region_exclude = re.compile(r'(intron|intergenic|utr)', re.IGNORECASE)
    counts = []
    missing = []
    details = []
    for sid in sorted(carriers, key=lambda x: (not x.isdigit(), int(x) if x.isdigit() else x)):
        member = variant_members.get(sid)
        if member is None:
            missing.append(sid)
            continue
        rows = read_xlsx_bytes(archive.read(member))
        if len(rows) < 3:
            raise RuntimeError('Variant workbook has fewer than three rows: ' + member)
        header = index_headers(rows[1])
        needed = ['Zygosity', 'Variant Allele Freq', 'Gene Names', 'Sequence Ontology (Combined)', 'Effect (Combined)']
        absent = [h for h in needed if h not in header]
        if absent:
            raise RuntimeError('Missing columns in ' + member + ': ' + ','.join(absent))
        in_chip_i = header.get('In_CHIP')
        count = 0
        for r in rows[2:]:
            if in_chip_i is not None:
                in_chip = cell(r, in_chip_i).lower() == 'true'
            else:
                in_chip = bool(split_genes(cell(r, header['Gene Names'])) & chip_genes)
            if not in_chip:
                continue
            if cell(r, header['Zygosity']).lower() == 'reference':
                continue
            region_text = cell(r, header['Sequence Ontology (Combined)']) + ' ' + cell(r, header['Effect (Combined)'])
            if region_exclude.search(region_text):
                continue
            vaf = parse_float(cell(r, header['Variant Allele Freq']))
            if vaf is None:
                continue
            if vaf < 0.3:
                count += 1
        counts.append(count)
        details.append((sid, carriers[sid]['role'], carriers[sid]['blm'], count, os.path.basename(member)))

if missing:
    raise RuntimeError('Missing variant workbook(s) for carrier sample ID(s): ' + ','.join(missing))
if not counts:
    raise RuntimeError('No BLM carrier samples were available for median calculation')
med = statistics.median(counts)
answer = str(int(med)) if float(med).is_integer() else str(med)
with open(answer_path, 'w') as out:
    out.write(answer + '\\n')
with open(counts_path, 'w') as out:
    out.write('sample_id\\tstatus\\tblm_mutation_status\\tsomatic_chip_variant_count\\tvariant_workbook\\n')
    for row in details:
        out.write('\\t'.join(map(str, row)) + '\\n')
with open(summary_path, 'w') as out:
    out.write('metric\\tvalue\\n')
    out.write('carrier_sample_count\\t' + str(len(counts)) + '\\n')
    out.write('chip_gene_count\\t' + str(len(chip_genes)) + '\\n')
    out.write('median_somatic_chip_variant_count\\t' + answer + '\\n')
'''
print(base64.b64encode(script.encode()).decode())
PY"

